    31	sub _read_state {
    32	    my $path = budget_state_file();
    33	    my %state;
    34	    if (open my $fh, '<', $path) {
    35	        my $bytes = 0;
    36	        while (my $line = <$fh>) {
    37	            $bytes += length($line);
    38	            $bytes <= MAX_STATE_BYTES or fatal("zram writeback budget state $path is too large");
    39	            length($line) <= MAX_STATE_LINE_BYTES or fatal("zram writeback budget state $path has an oversized line");
    40	            chomp $line;
    41	            my ($key, $value) = $line =~ /\A([A-Za-z0-9_]+)=(.*)\z/;
    42	            next if !defined $key;
    43	            $value =~ s/[\r\n]//g;
    44	            $state{$key} = $value;
    45	        }
    46	        close $fh;
    47	    }
