    57	    for my $key (sort keys %{$state}) {
    58	        my $value = defined $state->{$key} ? $state->{$key} : '';
    59	        $value =~ s/[\r\n]//g;
    60	        print {$fh} "$key=$value\n" or fatal("failed to write $tmp: $!");
    61	    }
