   174	sub retain {
   175	    my ($self, $source, $metadata) = @_;
   176	    ExternalSoftware::Servicing::Atomic->ensure_root_directory($self->directory(), 0755);
   177	    -f $source && !-l $source or die "validated Debian package disappeared before retention\n";
   178	    my $name = $self->_archive_name(
   179	        @{$metadata}{qw(package version architecture)},
   180	    );
   181	    my $destination = ExternalSoftware::Servicing::Atomic->assert_child($self->directory(), $name);
   182	    if (!-e $destination) {
   183	        my $temporary = "$destination.tmp.$$";
   184	        copy($source, $temporary) or die "failed to retain validated Debian package: $!\n";
   185	        chmod 0644, $temporary or die "failed to set retained package mode: $!\n";
   186	        rename $temporary, $destination or die "failed to publish retained package: $!\n";
   187	    }
   188	    $self->refresh();
   189	    return $destination;
