   192	sub repair {
   193	    my ($self, $deb, $spec) = @_;
   194	    my @packages = @{$spec->{packages}};
   195	    for my $package (@packages) {
   196	        my $status = $self->_capture('/usr/bin/dpkg-query', '-W', '-f=${Status}', $package) // q{};
   197	        next if $status eq q{} || $status eq 'unknown ok not-installed'
   198	            || $status eq 'deinstall ok config-files' || $status eq 'purge ok not-installed';
   199	        if ($status eq 'install ok installed'
   200	            && -x $spec->{executable}
   201	            && -r $spec->{desktop}
   202	            && (!defined $spec->{library} || $spec->{library} eq q{} || -r $spec->{library})) {
   203	            return 1;
   204	        }
   205	        my $version = $self->_capture('/usr/bin/dpkg-query', '-W', '-f=${Version}', $package) // q{};
   206	        chomp $version;
   207	        my $archive = eval {
   208	            File::Spec->catfile($self->directory(), $self->_archive_name($package, $version, 'amd64'));
   209	        };
   210	        if (defined $archive && -f $archive && !-l $archive) {
   211	            my $metadata = eval {
   212	                $deb->validate(
   213	                    label => "$spec->{label} retained archive",
   214	                    path => $archive,
   215	                    packages => $spec->{packages},
   216	                    executable => $spec->{executable},
   217	                    desktop => $spec->{desktop},
   218	                    library => $spec->{library},
   219	                );
   220	            };
   221	            if ($metadata
   222	                && system('/usr/bin/dpkg', '--install', $archive) == 0
   223	                && system('/usr/bin/dpkg', '--configure', $package) == 0
   224	                && -x $spec->{executable} && -r $spec->{desktop}) {
   225	                return 1;
   226	            }
   227	        }
   228	        if ($status ne 'install ok installed') {
   229	            system('/usr/bin/dpkg', '--remove', '--force-remove-reinstreq', $package) == 0
   230	                || system('/usr/bin/dpkg', '--purge', '--force-all', $package) == 0
   231	                or die "$spec->{label} could not be removed from unrecoverable dpkg state\n";
   232	        }
   233	        return 0;
   234	    }
   235	    return 1;
   236	}
