    30	    my ($self) = @_;
    31	    my $path = $self->lock_path();
    32	    ExternalSoftware::Servicing::Atomic->assert_absolute_path('managed updater lock', $path);
    33	    sysopen my $fh, $path, O_CREAT | O_NOFOLLOW | O_RDWR, 0600
    34	        or die "failed to open updater lock: $!\n";
    35	    fcntl($fh, F_SETFD, FD_CLOEXEC) or die "failed to protect updater lock: $!\n";
